// The browser posts the cart to /api/checkout, which creates a pending order
// and a payment session with the provider, then redirects the browser there.
export async function startCheckout(cart: Cart): Promise<Redirect> {
  const order = await orders.createPending(cart);
  const session = await provider.createSession({ orderId: order.id, amount: cart.total });
  return redirect(session.url);
}

