// The provider calls this when the payment settles. A valid signature marks
// the order paid and queues the receipt email; a failed payment marks it failed.
export async function onProviderEvent(event: ProviderEvent): Promise<void> {
  verifySignature(event);
  if (event.type === "payment.succeeded") {
    await orders.markPaid(event.orderId);
    await queue.add("send-receipt", { orderId: event.orderId });
  } else if (event.type === "payment.failed") {
    await orders.markFailed(event.orderId);
  }
}

