export function PricingCard({ plan, annual }: { plan: Plan; annual: boolean }) {
  const price = annual ? plan.yearly / 12 : plan.monthly;
  return (
    <section className="card">
      <h3>{plan.name}</h3>
      <p className="price">${price}/mo</p>
      {annual ? <p className="note">Billed yearly</p> : null}
      <ul>{plan.features.map((feature) => <li key={feature}>{feature}</li>)}</ul>
      <button>Choose {plan.name}</button>
    </section>
  );
}

